sysauto_script.script:
// --- CONSTs ---
const TABLE = 'x_1935344_edx_employee';
// DOB = Date of Birth
const DOB_FIELD = 'date_birth';
const AGE_FIELD = 'age';

// --- MAIN LOGIC ---
// get current Date, month and day
var currentDate = new GlideDate();

var currentMonth = currentDate.getByFormat("MM");
var currentDay = currentDate.getByFormat("dd");

var gr = new GlideRecord(TABLE);

// only user with active=true and NOT NULL date_birth field
gr.addNotNullQuery(DOB_FIELD);
gr.addQuery("active", true);

gr.query();

while (gr.next()) {

    var dobStr = gr.getValue(DOB_FIELD);

    // check if is birth date
    var birthDate = new GlideDate();
    birthDate.setValue(dobStr);

    var monthBirth = birthDate.getByFormat("MM");
    var dayBirth = birthDate.getByFormat("dd");

    // if not is, so continue
    if (currentMonth != monthBirth || currentDay != dayBirth) {
        continue;
    }

    var age = calcAge(currentDate, birthDate);

    var oldAge = gr.getValue("age");

    // if current age is equal loaded age, so continue
    if (oldAge == age) {
        continue;
    }

    // stores information on which user updated
    gs.info("Date of birth upload changes (USER:." + gr.getValue("name") + ";OldAge:." + oldAge + ";Age:." + age + ")");

    gr.setValue(AGE_FIELD, age);
    gr.update();
}

function calcAge(currentDate, birthDate) {

    var age = parseInt(currentDate.getByFormat('yyyy'), 10) - parseInt(birthDate.getByFormat("yyyy"), 10);

    var tMD = currentDate.getByFormat('MMdd');
    var bMD = birthDate.getByFormat('MMdd');

    if (tMD < bMD) {
        age--;
    }

    return age;
}
